// Bundles every recipes/*.vep.json into recipes/recipes.js so the folder view
// works from file:// (no fetch). Re-run after adding or editing a recipe file:
//   node build-recipes.js
const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, 'recipes');
const items = fs.readdirSync(dir)
    .filter(f => f.endsWith('.vep.json'))
    .sort()
    .map(f => ({
        id: 'file:' + f.replace(/\.vep\.json$/, ''),
        recipe: JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'))
    }));

fs.writeFileSync(
    path.join(dir, 'recipes.js'),
    '// Generated by build-recipes.js -- do not edit.\nwindow.VEP_RECIPE_FOLDER = ' + JSON.stringify(items) + ';\n'
);
console.log(`Bundled ${items.length} recipes.`);
